L000767	\section{Numerical evaluation of the compressible and incompressible energy spectra}
L000768	Given the weighted superfluid velocity $\boldsymbol{u}$, we outline the procedure to extract its irrotational and solenoidal components, $\boldsymbol{u}_{c}$ and $\boldsymbol{u}_{i}$, respectively. 
L000769	
L000770	
L000771	Using the Green's function \cite{Watanabe2013}, any 
L000772	two-dimensional vector field $\boldsymbol{V} \left( \boldsymbol{r}\right)$ can be expressed as 
L000773	\begin{equation}\label{vector_integral_identity}
L000774	\boldsymbol{V} \left( \boldsymbol{r}\right) 
L000775	= 
L000776	\int 
L000777	\boldsymbol{V} \left( \boldsymbol{r}^{\prime}\right) 
L000778	\delta \left( \boldsymbol{r} - \boldsymbol{r}^{\prime} \right) 
L000779	\, d^2 \boldsymbol{r}^{\prime} 
L000780	= 
L000781	\nabla^2 
L000782	\left\lbrack 
L000783	\frac{1}{2 \pi} 
L000784	\int 
L000785	\boldsymbol{V} \left( \boldsymbol{r}^{\prime}\right) 
L000786	\ln \left( \frac{\left\vert \boldsymbol{r} - \boldsymbol{r}^{\prime} \right\vert}{l} \right) 
L000787	\, 
L000788	d^2 \boldsymbol{r}^{\prime} 
L000789	\right\rbrack 
L000790	, 
L000791	\end{equation}
L000792	where $\delta \left( \boldsymbol{r} \right)$ is the two-dimensional Dirac delta function 
L000793	and $l$ is a constant with units of length. 
L000794	Applying Eq. (\ref{vector_integral_identity}) to $\boldsymbol{u}(\boldsymbol{r})$ yields $\boldsymbol{u}(\boldsymbol{r})=\nabla^{2}\boldsymbol{b}(\boldsymbol{r})$, where $
L000795	\boldsymbol{b} \left( \boldsymbol{r}\right) 
L000796	\coloneqq 
L000797	\left( 1 / 2 \pi \right) 
L000798	\int 
L000799	\boldsymbol{u} \left( \boldsymbol{r}^{\prime} \right) 
L000800	\ln \left( \left\vert \boldsymbol{r} - \boldsymbol{r}^{\prime} \right\vert / l \right) 
L000801	\, d^2 \boldsymbol{r}^{\prime} 
L000802	$.
L000803	Using the vector identity $\nabla \times \left( \nabla \times \boldsymbol{A} \right) = \nabla \left( \nabla \cdot \boldsymbol{A} \right) - \nabla^2 \boldsymbol{A}$, we can thus decompose $\boldsymbol{u}$ into:
L000804	\begin{equation}
L000805	\boldsymbol{u}_{c} \left( \boldsymbol{r}, t \right) 
L000806	= 
L000807	\nabla 
L000808	\left\lbrack 
L000809	\nabla 
L000810	\cdot 
L000811	\boldsymbol{b} \left( \boldsymbol{r}, t \right) 
L000812	\right\rbrack 
L000813	, \quad 
L000814	\boldsymbol{u}_{i} \left( \boldsymbol{r}, t \right) 
L000815	= 
L000816	- 
L000817	\nabla 
L000818	\times 
L000819	\left\lbrack 
L000820	\nabla 
L000821	\times 
L000822	\boldsymbol{b} \left( \boldsymbol{r}, t \right) 
L000823	\right\rbrack,
L000824	\label{Eq:app:B:vc_vic_as_b}
L000825	\end{equation}
L000826	satisfying 
L000827	$\nabla \times \boldsymbol{u}_{c} \left( \boldsymbol{r}, t \right) = 0$ and 
L000828	$\nabla \cdot \boldsymbol{u}_{i} \left( \boldsymbol{r}, t \right) = 0$.
L000829	
L000830	
L000831	In Fourier space, we have $\boldsymbol{\tilde{u}}(\boldsymbol{k})=-{k}^{2}\boldsymbol{\tilde{b}}(\boldsymbol{k})$, with $\boldsymbol{\tilde{b}} \left( \boldsymbol{k}, t \right) 
L000832	= 
L000833	\left( 1 / 2 \pi \right) 
L000834	\int 
L000835	e^{- i \boldsymbol{k} \cdot \boldsymbol{r}} 
L000836	\boldsymbol{b} \left( \boldsymbol{r}, t \right) 
L000837	\, d^2 \boldsymbol{r} $.
L000838	Inserting this into Eq. (\ref{Eq:app:B:vc_vic_as_b}) gives:
L000839	\begin{equation}\label{u_c_and_u_i_expressed_as_k_integrals}
L000840	\boldsymbol{u}_{c} \left( \boldsymbol{r}, t \right) 
L000841	=  
L000842	\frac{1}{2 \pi} 
L000843	\int 
L000844	\frac{\boldsymbol{k}}{k^2} 
L000845	\left\lbrack 
L000846	\boldsymbol{k} 
L000847	\cdot 
L000848	\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right) 
L000849	\right\rbrack 
L000850	e^{i \boldsymbol{k} \cdot \boldsymbol{r}} 
L000851	\, d^2 \boldsymbol{k} 
L000852	, \quad 
L000853	\boldsymbol{u}_{i} \left( \boldsymbol{r}, t \right) 
L000854	= 
L000855	- 
L000856	\frac{1}{2 \pi} 
L000857	\int 
L000858	\frac{\boldsymbol{k}}{k^2} 
L000859	\times 
L000860	\left\lbrack 
L000861	\boldsymbol{k} 
L000862	\times 
L000863	\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right) 
L000864	\right\rbrack 
L000865	e^{i \boldsymbol{k} \cdot \boldsymbol{r}} 
L000866	\, d^2 \boldsymbol{k} 
L000867	, 
L000868	\end{equation}
L000869	where $k \coloneqq \left\vert \boldsymbol{k} \right\vert$. 
L000870	Thus, in momentum space, the compressible and incompressible components of $\boldsymbol{u}$ read
L000871	$
L000872	\boldsymbol{\tilde{u}}_{c} \left( \boldsymbol{k}, t \right) 
L000873	= 
L000874	\boldsymbol{e}_k 
L000875	\left\lbrack 
L000876	\boldsymbol{e}_k 
L000877	\cdot 
L000878	\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right) 
L000879	\right\rbrack 
L000880	$, and 
L000881	$
L000882	\boldsymbol{\tilde{u}}_{i} \left( \boldsymbol{k}, t \right) 
L000883	= 
L000884	\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right) 
L000885	- 
L000886	\boldsymbol{\tilde{u}}_{c} \left( \boldsymbol{k}, t \right) 
L000887	$ where $\boldsymbol{e}_k \coloneqq \boldsymbol{k} / k$.
L000888	Finally, the compressible and incompressible energy spectra are given by
L000889	\begin{equation}\label{E_c_k_and_E_i_k_equations}
L000890	E_{c} \left( k 
L000891	, t 
L000892	\right) 
L000893	= 
L000894	\frac{k}{2}
L000895	\int_{0}^{2 \pi} 
L000896	\left\lbrack 
L000897	\boldsymbol{e}_k 
L000898	\cdot 
L000899	\boldsymbol{\tilde{u}}^{*} \left( \boldsymbol{k}, t \right) 
L000900	\right\rbrack 
L000901	\left\lbrack 
L000902	\boldsymbol{e}_k 
L000903	\cdot 
L000904	\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right) 
L000905	\right\rbrack 
L000906	\, d \varphi_k 
L000907	, \quad 
L000908	E_{i} \left( k 
L000909	, t 
L000910	\right) 
L000911	= 
L000912	\frac{k}{2}
L000913	\int_{0}^{2 \pi} 
L000914	\boldsymbol{\tilde{u}}^{*} \left( \boldsymbol{k}, t \right) 
L000915	\cdot 
L000916	\boldsymbol{\tilde{u}} \left( \boldsymbol{k}, t \right) 
L000917	\, d \varphi_k 
L000918	- 
L000919	E_{c} \left( k \right) 
L000920	, 
L000921	\end{equation}
L000922	where $\varphi_k$ is the azimuthal angle of $\boldsymbol{k}$, i.e., $\boldsymbol{e}_k = \left( \cos \varphi_k, \sin \varphi_k \right)$. 
L000923	As our analysis mainly focuses on the system at equilibration time $t_{\textrm{eq}}$, we will omit the time argument for brevity and denote $E_{c, i}(k) \coloneqq E_{c, i}(k, t_{\textrm{eq}})$. 
