L000953	\section{Numerical evaluation of the velocity structure function}
L000954	To numerically calculate the velocity structure function 
L000955	\begin{equation}
L000956	S_p \left( r \right) 
L000957	\coloneqq 
L000958	\frac{1}{2 \pi L^2} 
L000959	\int_{0}^{2 \pi} 
L000960	\int_{0}^{L} 
L000961	\int_{0}^{L} 
L000962	\left\vert 
L000963	\left\lbrack 
L000964	\boldsymbol{u}_i \left( \boldsymbol{R} + \boldsymbol{r} \right) 
L000965	- 
L000966	\boldsymbol{u}_i \left( \boldsymbol{R} \right) 
L000967	\right\rbrack 
L000968	\cdot 
L000969	\boldsymbol{e}_r 
L000970	\right\vert^p 
L000971	\; 
L000972	d R_x \; 
L000973	d R_y \; 
L000974	d \varphi 
L000975	, 
L000976	\label{supp:eq:Sp}
L000977	\end{equation}
L000978	where $\boldsymbol{e}_r \coloneqq \boldsymbol{r} / r = \left( \cos \varphi, \sin \varphi \right)$ is the unit vector along $\boldsymbol{r}$ \cite{Ciliberto1994,Frisch1995}, we compute the velocity increments using the discrete Fourier transform, implemented via the Julia package \texttt{FFTW.jl}. 
L000979	Let $\nu_j \coloneqq \left( j - 1 \right) L_{\nu} / N_{\nu}$ for $1 \le j \le N_{\nu}$ with $\nu = x, y$. The weighted superfluid velocity $\boldsymbol{u} \left( x_j, y_l\right)$ can then be written as 
L000980	\begin{equation}
L000981	\boldsymbol{u} \left( x_j, y_l \right) 
L000982	= 
L000983	\frac{1}{N_x N_y} 
L000984	\sum_{n_x = 1}^{N_x} 
L000985	\sum_{n_y = 1}^{N_y} 
L000986	\boldsymbol{\tilde{u}}\left( n_x - 1, n_y - 1 \right) 
L000987	e^{2 \pi i \left( n_x - 1 \right) \left( j - 1 \right) / N_x}
L000988	e^{2 \pi i \left( n_y - 1 \right) \left( l - 1 \right) / N_y}
L000989	,
L000990	\end{equation}
L000991	where we used $\boldsymbol{k} / 2 \pi = \left( \left( n_x - 1 \right) / L_x, \left( n_y - 1 \right) / L_y \right)$ in the discrete Fourier space. 
L000992	Since $\boldsymbol{u} \left( x_j, y_l \right)$ is real, its derivatives must also be real. 
L000993	Using the identity $\exp \left( 2 \pi i \left( n_{\nu} - 1 \right) \left( j - 1 \right) / N_{\nu} \right) = \exp \left( 2 \pi i \left( n_{\nu} - 1 - N_{\nu} \right) \left( j - 1 \right) / N_{\nu} \right)$ for any integers $1 \le n_{\nu} \le N_{\nu}$ and $1 \le j \le N_{\nu}$, in order to make $\boldsymbol{u}_i \left( x_j, y_l \right)$ real, one should use the following expression: 
L000994	\begin{equation}
L000995	\boldsymbol{u}_i \left( x_j, y_l \right) 
L000996	= 
L000997	\frac{1}{N_x N_y} 
L000998	\sum_{n_x = 1}^{N_x} 
L000999	\sum_{n_y = 1}^{N_y} 
L001000	\frac{
L001001	\boldsymbol{k} \left( n_x, n_y \right) 
L001002	}{
L001003	k^2 \left( n_x, n_y \right) 
L001004	} 
L001005	\times 
L001006	\left\lbrack 
L001007	\boldsymbol{\tilde{u}}\left( n_x - 1, n_y - 1 \right) 
L001008	\times 
L001009	\boldsymbol{k} \left( n_x, n_y \right) 
L001010	\right\rbrack 
L001011	e^{2 \pi i \left( n_x - 1 \right) \left( j - 1 \right) / N_x}
L001012	e^{2 \pi i \left( n_y - 1 \right) \left( l - 1 \right) / N_y}
L001013	, 
L001014	\label{eq:app:u_i_discrete_space}
L001015	\end{equation}
L001016	with $\boldsymbol{k} \left( n_x, n_y \right) \coloneqq \sum_{\nu = x, y} k_{\nu} \left( n_x, n_y \right) \boldsymbol{e}_{\nu} $ and 
L001017	\begin{equation}
L001018	k_{\nu} \left( n_x, n_y \right) 
L001019	\coloneqq 
L001020	\left\{ 
L001021	\begin{array}{cc}
L001022	2 \pi i \left( n_{\nu} - 1 \right) / L_{\nu} 
L001023	, 
L001024	& 
L001025	\textrm{ if \; $1 \le n_{\nu} \le \left\lbrack N_{\nu} / 2 \right\rbrack_r + 1$,}
L001026	\\
L001027	\\
L001028	2 \pi i \left( n_{\nu} - 1 - N_{\nu} \right) / L_{\nu} 
L001029	, 
L001030	& 
L001031	\textrm{ otherwise,}
L001032	\end{array}
L001033	\right. 
L001034	\end{equation}
L001035	where $\left\lbrack x \right\rbrack_r$ is the greatest integer less than or equal to $x$, so that $- 2 \pi i \left\lbrack N_{\nu} / 2 \right\rbrack_r / L_{\nu} \le k_{\nu} \left( n_x, n_y \right) \le 2 \pi i \left\lbrack N_{\nu} / 2 \right\rbrack_r / L_{\nu}$. 
L001036	
L001037	
L001038	Note that, for any function $f \left( x, y \right)$ in the periodic system $f \left( x + L_x, y \right) = f \left( x, y + L_y \right) = f \left( x, y \right)$, 
L001039	\begin{equation}
L001040	\frac{1}{L_x L_y} 
L001041	\int_0^{L_x} 
L001042	\int_0^{L_y} 
L001043	f \left( x, y \right) \; 
L001044	d y \; 
L001045	d x 
L001046	= 
L001047	\frac{1}{N_x N_y} 
L001048	\sum_{j = 1}^{N_x} 
L001049	\sum_{l = 1}^{N_y} 
L001050	f \left( x_j, y_l \right) 
L001051	. 
L001052	\label{eq:app:spatial_numerical_integration}
L001053	\end{equation}
L001054	After numerically calculating $\boldsymbol{u}_i \left( x_j, y_l \right)$ via Eq. \eqref{eq:app:u_i_discrete_space}, 
L001055	we calculate 
L001056	$
L001057	\Delta \boldsymbol{u}_i \left( \boldsymbol{R}, \boldsymbol{r} \right) 
L001058	\coloneqq 
L001059	\boldsymbol{u}_i \left( \boldsymbol{R} + \boldsymbol{r} \right) 
L001060	- 
L001061	\boldsymbol{u}_i \left( \boldsymbol{R} \right) 
L001062	$ and then calculate $S_p \left( r \right)$ numerically as 
L001063	\begin{equation}
L001064	S_p \left( r \right) 
L001065	= 
L001066	\frac{1}{L^2} 
L001067	\int_{0}^{L} 
L001068	\int_{0}^{L} 
L001069	\left\lbrack 
L001070	\frac{1}{2 \pi} 
L001071	\int_0^{2 \pi} 
L001072	\left\vert 
L001073	\Delta \boldsymbol{u}_i \left( \boldsymbol{R}, \boldsymbol{r} \right) 
L001074	\cdot 
L001075	\boldsymbol{e}_r 
L001076	\right\vert^p \; 
L001077	d \varphi 
L001078	\right\rbrack \;
L001079	d R_x \; 
L001080	d R_y 
L001081	= 
L001082	\frac{1}{N^2_x} 
L001083	\sum_{j, l = 1}^{N_x} 
L001084	\left\lbrack 
L001085	\frac{1}{2 \pi} 
L001086	\int_{0}^{2 \pi} 
L001087	\left\vert 
L001088	\Delta \boldsymbol{u}_i \left( X_j, Y_l, \boldsymbol{r} \right) 
L001089	\cdot 
L001090	\boldsymbol{e}_r 
L001091	\right\vert^p \; 
L001092	d \varphi 
L001093	\right\rbrack 
L001094	,
L001095	\end{equation}
L001096	with $X_j \coloneqq \left( j - 1 \right) L / N_x$ and $Y_l \coloneqq \left( l - 1 \right) L / N_x$. 
